refentry.refsect1:
  &reftitle.description;

   trueusort
   arrayarray
   callablecallback


क्रम निर्धारण गर्नका लागि user-supplied comparison function प्रयोग गरेर array लाई values अनुसार in place sort गर्दछ।
  &note.sort-unstable;
  &note.no-key-association;

  &reftitle.examples;



    usort को उदाहरण


<?php
function cmp($a, $b)
{
    if ($a == $b) {
        return 0;
    }
    return ($a < $b) ? -1 : 1;
}

$a = array(3, 2, 5, 6, 1);

usort($a, "cmp");

foreach ($a as $key => $value) {
    echo "$key: $value\n";
}
?>


    &example.outputs;


0: 1
1: 2
2: 3
3: 5
4: 6



आन्तरिक comparison लाई अझ सरल बनाउन spaceship operator प्रयोग गर्न सकिन्छ।


<?php
function cmp($a, $b)
{
    return $a <=> $b;
}

$a = array(3, 2, 5, 6, 1);

usort($a, "cmp");

foreach ($a as $key => $value) {
    echo "$key: $value\n";
}
?>






स्पष्ट रूपमा यस सामान्य अवस्थामा sort function बढी उपयुक्त हुनेछ।




    multi-dimensional array प्रयोग गरिएको usort को उदाहरण


<?php
function cmp($a, $b)
{
    return strcmp($a["fruit"], $b["fruit"]);
}

$fruits[0]["fruit"] = "lemons";
$fruits[1]["fruit"] = "apples";
$fruits[2]["fruit"] = "grapes";

usort($fruits, "cmp");

foreach ($fruits as $key => $value) {
    echo "\$fruits[$key]: " . $value["fruit"] . "\n";
}
?>


    &example.outputs;


$fruits[0]: apples
$fruits[1]: grapes
$fruits[2]: lemons



एउटा multi-dimensional array लाई sort गर्दा, $a र $b मा array को पहिलो index का references समावेश हुन्छन्।





    एउटा object को member function प्रयोग गरिएको usort को उदाहरण


<?php
class TestObj {
    public string $name;

    function __construct($name)
    {
        $this->name = $name;
    }

    /* This is the static comparing function: */
    static function cmp_obj($a, $b)
    {
        return strtolower($a->name) <=> strtolower($b->name);
    }
}

$a[] = new TestObj("c");
$a[] = new TestObj("b");
$a[] = new TestObj("d");

usort($a, [TestObj::class, "cmp_obj"]);

foreach ($a as $item) {
    echo $item->name . "\n";
}
?>


    &example.outputs;


b
c
d




    एउटा multi-dimensional array लाई sort गर्न closure प्रयोग गरिएको usort को उदाहरण


<?php
$array[0] = array('key_a' => 'z', 'key_b' => 'c');
$array[1] = array('key_a' => 'x', 'key_b' => 'b');
$array[2] = array('key_a' => 'y', 'key_b' => 'a');

function build_sorter($key) {
    return function ($a, $b) use ($key) {
        return strnatcmp($a[$key], $b[$key]);
    };
}

usort($array, build_sorter('key_b'));

foreach ($array as $item) {
    echo $item['key_a'] . ', ' . $item['key_b'] . "\n";
}
?>


    &example.outputs;


y, a
x, b
z, c




    spaceship operator प्रयोग गरिएको usort को उदाहरण

spaceship operator ले धेरै axes मा compound values को सरल तुलना गर्न अनुमति दिन्छ। तलको उदाहरणले $people लाई last name अनुसार, र यदि last name मिल्छ भने first name अनुसार sort गर्नेछ।


<?php
$people[0] = ['first' => 'Adam', 'last' => 'West'];
$people[1] = ['first' => 'Alec', 'last' => 'Baldwin'];
$people[2] = ['first' => 'Adam', 'last' => 'Baldwin'];

function sorter(array $a, array $b) {
    return [$a['last'], $a['first']] <=> [$b['last'], $b['first']];
}

usort($people, 'sorter');

foreach ($people as $person) {
    print $person['last'] . ', ' . $person['first'] . PHP_EOL;
}
?>


    &example.outputs;


Baldwin, Adam
Baldwin, Alec
West, Adam
